import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import DashboardLayout from '../../layouts/DashboardLayout';
import { complaintAPI } from '../../services/api';
import { StatusBadge, PriorityBadge, SlaBadge } from '../../components/StatusBadge';
import LoadingSpinner from '../../components/LoadingSpinner';
import toast from 'react-hot-toast';
import { format } from 'date-fns';

const STATUSES = ['assigned', 'in_progress', 'resolved'];

const OfficerComplaintDetail = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [complaint, setComplaint] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [status, setStatus] = useState('');
    const [note, setNote] = useState('');
    const [proofFiles, setProofFiles] = useState([]);
    const [proofNote, setProofNote] = useState('');
    const [submitting, setSubmitting] = useState(false);
    const [comment, setComment] = useState('');
    const BASE_URL = process.env.REACT_APP_API_URL?.replace('/api', '') || 'http://localhost:5000';

    const refetch = () => complaintAPI.getById(id).then(({ data }) => { setComplaint(data.data); setStatus(data.data.status); });

    useEffect(() => {
        setError(null);
        refetch().catch((err) => {
            const msg = err.response?.status === 404
                ? 'Complaint not found. It may have been removed or the ID is invalid.'
                : (err.response?.data?.message || 'Failed to load complaint. Please try again.');
            setError(msg);
        }).finally(() => setLoading(false));
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [id]);

    const handleStatusUpdate = async () => {
        setSubmitting(true);
        try {
            await complaintAPI.updateStatus(id, { status, note });
            toast.success('Status updated');
            setNote('');
            refetch();
        } catch (err) { toast.error(err.response?.data?.message || 'Failed'); }
        finally { setSubmitting(false); }
    };

    const handleProofUpload = async (e) => {
        e.preventDefault();
        if (!proofFiles.length) { toast.error('Upload at least one proof image'); return; }
        setSubmitting(true);
        const formData = new FormData();
        proofFiles.forEach(f => formData.append('proofImages', f));
        formData.append('note', proofNote);
        try {
            await complaintAPI.uploadProof(id, formData);
            toast.success('Resolution proof uploaded');
            setProofFiles([]); setProofNote('');
            refetch();
        } catch (err) { toast.error(err.response?.data?.message || 'Failed'); }
        finally { setSubmitting(false); }
    };

    const handleComment = async (e) => {
        e.preventDefault();
        if (!comment.trim()) return;
        try {
            await complaintAPI.addComment(id, { text: comment, isInternal: false });
            toast.success('Comment added');
            setComment('');
            refetch();
        } catch { toast.error('Failed'); }
    };

    if (loading) return <DashboardLayout><div className="flex justify-center py-20"><LoadingSpinner size="lg" /></div></DashboardLayout>;

    if (error || !complaint) return (
        <DashboardLayout>
            <div className="max-w-lg mx-auto mt-16 text-center animate-fade-in">
                <div className="card p-10">
                    <div className="text-6xl mb-4">🔍</div>
                    <h1 className="text-xl font-bold text-gray-800 mb-2">Complaint Not Found</h1>
                    <p className="text-gray-500 text-sm mb-6">
                        {error || 'The complaint you are looking for does not exist or you do not have permission to view it.'}
                    </p>
                    <div className="flex gap-3 justify-center">
                        <button onClick={() => navigate(-1)} className="btn-secondary text-sm">← Go Back</button>
                        <button onClick={() => { setLoading(true); setError(null); refetch().catch(err => setError(err.response?.data?.message || 'Failed')).finally(() => setLoading(false)); }} className="btn-primary text-sm">Retry</button>
                    </div>
                </div>
            </div>
        </DashboardLayout>
    );

    return (
        <DashboardLayout>
            <div className="max-w-3xl mx-auto space-y-5 animate-fade-in">
                <div className="card">
                    <div className="flex items-start justify-between gap-3 flex-wrap">
                        <div>
                            <code className="text-xs bg-gray-100 px-2 py-0.5 rounded font-mono text-gray-500">{complaint.complaintId}</code>
                            <h1 className="text-xl font-bold text-gray-900 mt-1">{complaint.title}</h1>
                            <p className="text-sm text-gray-500">📍 {complaint.address}</p>
                            {complaint.citizen?.name && <p className="text-xs text-gray-400 mt-0.5">Submitted by: {complaint.citizen.name}</p>}
                        </div>
                        <div className="flex flex-col items-end gap-1">
                            <StatusBadge status={complaint.status} />
                            <PriorityBadge priority={complaint.priority} />
                            <SlaBadge slaDueAt={complaint.slaDueAt} status={complaint.status} />
                        </div>
                    </div>
                    <div className="mt-4 p-3 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-700 leading-relaxed">{complaint.description}</p>
                    </div>
                    {complaint.images?.length > 0 && (
                        <div className="grid grid-cols-3 gap-2 mt-4">
                            {complaint.images.map((img, i) => (
                                <img key={i} src={`${BASE_URL}${img}`} alt="Complaint" className="rounded-lg object-cover h-24 w-full" />
                            ))}
                        </div>
                    )}
                </div>

                {/* Status update */}
                {complaint.status !== 'closed' && (
                    <div className="card">
                        <h2 className="text-sm font-semibold text-gray-700 mb-3">Update Status</h2>
                        <div className="flex gap-2 mb-2 flex-wrap">
                            {STATUSES.map(s => (
                                <button key={s} onClick={() => setStatus(s)}
                                    className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${status === s ? 'bg-primary-600 text-white border-primary-600' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}>
                                    {s.replace('_', ' ')}
                                </button>
                            ))}
                        </div>
                        <textarea value={note} onChange={e => setNote(e.target.value)} placeholder="Add a note about this status change..." className="input-field text-sm resize-none mb-2" rows={2} />
                        <button onClick={handleStatusUpdate} disabled={submitting} className="btn-primary text-sm">
                            {submitting ? 'Updating...' : 'Update Status'}
                        </button>
                    </div>
                )}

                {/* Resolution proof upload */}
                {['in_progress', 'assigned'].includes(complaint.status) && (
                    <div className="card border-green-200">
                        <h2 className="text-sm font-semibold text-green-800 mb-3">📸 Upload Resolution Proof</h2>
                        <form onSubmit={handleProofUpload} className="space-y-3">
                            <input type="file" accept="image/*" multiple onChange={e => setProofFiles(Array.from(e.target.files))}
                                className="block w-full text-sm text-gray-500 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-green-50 file:text-green-700 hover:file:bg-green-100" />
                            <textarea value={proofNote} onChange={e => setProofNote(e.target.value)} placeholder="Describe resolution..." className="input-field text-sm resize-none" rows={2} />
                            <button type="submit" disabled={submitting} className="btn-primary text-sm bg-green-600 hover:bg-green-700">
                                {submitting ? 'Uploading...' : 'Submit Proof & Mark Resolved'}
                            </button>
                        </form>
                    </div>
                )}

                {/* Timeline */}
                {complaint.auditTrail?.length > 0 && (
                    <div className="card">
                        <h2 className="text-sm font-semibold text-gray-700 mb-4">Activity Timeline</h2>
                        <div className="relative space-y-4 before:absolute before:top-0 before:bottom-0 before:left-3 before:w-0.5 before:bg-gray-200">
                            {[...complaint.auditTrail].reverse().map((entry, i) => (
                                <div key={i} className="flex gap-4 relative pl-8">
                                    <div className="absolute left-0 top-1 w-6 h-6 bg-white border-2 border-primary-400 rounded-full flex items-center justify-center">
                                        <div className="w-2 h-2 bg-primary-500 rounded-full" />
                                    </div>
                                    <div>
                                        <p className="text-sm font-medium text-gray-800 capitalize">{entry.action?.replace(/_/g, ' ')}</p>
                                        {entry.performedByName && <p className="text-xs text-gray-500">By {entry.performedByName}</p>}
                                        {entry.note && <p className="text-xs text-gray-400 italic">{entry.note}</p>}
                                        <p className="text-xs text-gray-400">{format(new Date(entry.timestamp), 'dd MMM yyyy, hh:mm a')}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* Comments */}
                <div className="card">
                    <h2 className="text-sm font-semibold text-gray-700 mb-3">Comments</h2>
                    <div className="space-y-3 mb-3">
                        {complaint.comments?.length === 0 && <p className="text-sm text-gray-400 text-center py-3">No comments yet</p>}
                        {complaint.comments?.map((c, i) => (
                            <div key={i} className={`flex gap-3 ${c.isInternal ? 'opacity-70' : ''}`}>
                                <div className="w-7 h-7 bg-gray-200 rounded-full flex items-center justify-center flex-shrink-0">
                                    <span className="text-xs font-semibold">{c.author?.name?.[0]?.toUpperCase()}</span>
                                </div>
                                <div className={`rounded-lg p-2.5 flex-1 text-sm ${c.isInternal ? 'bg-yellow-50 border border-yellow-200' : 'bg-gray-50'}`}>
                                    <p className="text-xs font-semibold text-gray-600">{c.author?.name} {c.isInternal && <span className="text-yellow-600">(Internal)</span>}</p>
                                    <p className="text-gray-700 mt-0.5">{c.text}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                    <form onSubmit={handleComment} className="flex gap-2">
                        <input value={comment} onChange={e => setComment(e.target.value)} placeholder="Add a comment..." className="input-field text-sm flex-1" />
                        <button type="submit" className="btn-primary text-sm flex-shrink-0">Send</button>
                    </form>
                </div>
            </div>
        </DashboardLayout>
    );
};

export default OfficerComplaintDetail;
